    record U(int umur) {
        U {
            if (umur < 0) throw new IllegalArgumentException("minus");
        }
    }

    public static void main(String[] args) {
        try {
            new U(-1);
        } catch (IllegalArgumentException e) {
            System.out.println("Ditolak " + e.getMessage());
        }
    }
}

